edits.find:
toast[type](finalMessage, {
  duration,
  action: undoable
    ? {
        label: translate("ra.action.undo"),
        onClick: handleUndo,
      }
    : undefined,
  onDismiss: handleExited,
  onAutoClose: handleExited,
});

edits.replace:
setEcho(typeof finalMessage === "string" ? finalMessage : "");
toast[type](finalMessage, {
  duration,
  action: undoable
    ? {
        label: translate("ra.action.undo"),
        onClick: handleUndo,
      }
    : undefined,
  onDismiss: handleExited,
  onAutoClose: handleExited,
});
